template.query:
mutation BulkCompleteTodos($todoIds: [ID!]!) {
  bulkUpdateNodes(
    nodeIds: $todoIds
    updates: [
      { attributeName: "status", value: "DONE" }
      { attributeName: "completed_at", value: "{{ now }}" }
    ]
  ) {
    success
    updatedCount
    totalCount
    errors {
      message
      nodeId
    }
    summary {
      previousStatus
      newStatus
      completedCount
    }
  }
}
